public static function calc( $in ) {
	try {
		$pid  = isset( $in['product_id'] ) ? (int) $in['product_id'] : 0;
		$w    = ( isset( $in['weight_kg'] ) && $in['weight_kg'] !== '' && $in['weight_kg'] !== null ) ? (float) $in['weight_kg'] : null;
		$ivc  = isset( $in['weight_interval_code'] ) ? (string) $in['weight_interval_code'] : null;
		$act  = ( isset( $in['activity_code'] ) && $in['activity_code'] !== '' ) ? (string) $in['activity_code'] : null;
		// S229 (2026-07-26): misraus serimo sluoksniui. Visi TRYS neprivalomi —
		// produkto puslapio kvietimai ju neturi, tad estimatorius grazins null.
		$mf_species = isset( $in['species'] ) ? (string) $in['species'] : null;
		$mf_ftype   = isset( $in['feeding_type'] ) ? (string) $in['feeding_type'] : null;
		$mf_wet_g   = ( isset( $in['wet_food_g'] ) && $in['wet_food_g'] !== '' ) ? (int) $in['wet_food_g'] : null;

		if ( $pid <= 0 ) { return self::shell( 'system_error', array( 0, 0, 0 ), array( 'SYSTEM_ERROR' ), 'Trūksta produkto.' ); }
		$product = function_exists( 'wc_get_product' ) ? wc_get_product( $pid ) : null;
		if ( ! $product ) { return self::shell( 'system_error', array( 0, 0, 0 ), array( 'SYSTEM_ERROR' ), 'Produktas nerastas.' ); }

		// --- Repository (esamas) ---
		$repo = new Petshop_Feeding_Repository();
		$rt   = $repo->get_for_product( $pid );
		switch ( $rt['status'] ) {
			case 'OK': break;
			case 'NO_ACTIVE_FEEDING_TABLE':
				return self::unavailable( array( 'NO_VERIFIED_TABLE' ), 'Šiam produktui dar nėra patikimos maitinimo lentelės.' );
			default:
				return self::shell( 'system_error', array( 0, 0, 0 ), array( 'SYSTEM_ERROR' ), 'Sistemos klaida.' );
		}
		// S228: numatytieji gamintojo stulpeliai kategorinems asims (pries support patikra).
		list( $rt, $need_age ) = self::apply_axis_defaults( $rt, $in );
		if ( $need_age ) { return self::needs_input_age(); }
		if ( ! empty( $rt['axis_policy'] ) ) {
			$cat_left = 0;
			foreach ( $rt['axis_policy'] as $an => $as ) { if ( ( is_array( $as ) ? ( $as['kind'] ?? null ) : null ) === 'categorical' ) { $cat_left++; } }
			if ( $cat_left === 0 && isset( $rt['support'] ) && $rt['support'] !== 'calculator_supported' ) { $rt['support'] = 'calculator_supported'; }
		}

		if ( isset( $rt['support'] ) && $rt['support'] !== 'calculator_supported' ) {
			return self::unavailable( array( 'NO_VERIFIED_TABLE' ), 'Ši lentelė kol kas nepalaikoma.' );
		}

		$rows     = isset( $rt['rows'] ) ? $rt['rows'] : array();
		$axis_np  = is_array( $rt['axis_policy'] ) ? $rt['axis_policy'] : array();
		$axis_flat = array();
		foreach ( $axis_np as $k => $v ) { $axis_flat[ $k ] = ( is_array( $v ) && isset( $v['policy'] ) ) ? $v['policy'] : $v; }
		$wb = ( ( $rt['weight_basis'] ?? 'current' ) === 'adult_expected' ) ? 'adult_expected' : 'current';
		// S228b: suaugusio tiketino svorio asiai galioja ta pati interpoliacijos
		// taisykle kaip current svoriui (tarp gretimu gamintojo tasku).
		if ( $wb === 'adult_expected' && isset( $axis_flat['adult_expected_weight_kg'] ) ) {
			$axis_flat['adult_expected_weight_kg'] = 'interpolation_allowed';
		}
		/* S273 KLAIDA IŠTAISYTA: current_weight_kg ašiai interpoliacija NEBUVO
		 * įjungta, nors S228b komentaras teigė, kad „galioja ta pati taisyklė".
		 * 254 iš 287 lentelių yra TAŠKINĖS (11, 15, 20, 25 kg...), tad bet koks
		 * svoris TARP taškų grąžindavo „Šiam svoriui nepavyko rasti normos" —
		 * 13 kg šuo su lentele nuo 11 kg negaudavo nieko.
		 * Interpoliacija tarp DVIEJŲ GRETIMŲ gamintojo taškų nėra prasimanymas —
		 * taip tokią lentelę skaito kiekvienas savininkas ir veterinaras.
		 * EKSTRAPOLIACIJA LIEKA DRAUDŽIAMA (Calculator 5c tikrina PRIEŠ 5d):
		 * už lentelės ribų → WEIGHT_OUT_OF_RANGE, kaip ir buvo.
		 * PATAISA: rakto axis_flat['current_weight_kg'] daugumai lentelių NĖRA
		 * (axis_resolution_policy DB yra NULL), todėl isset() tikrinimas
		 * niekada nesuveikdavo — nustatom NESĄLYGIŠKAI.
		 * SAUGU, nes Calculator 5a (range_match) ir 5b (tikslus taškas) veikia
		 * PRIEŠ 5d ir nepriklauso nuo politikos, o 5c ekstrapoliaciją blokuoja. */
		$cur_pol = isset( $axis_flat['current_weight_kg'] ) ? $axis_flat['current_weight_kg'] : null;
		if ( $cur_pol !== 'range_match' ) {
			$axis_flat['current_weight_kg'] = 'interpolation_allowed';
		}

